const {config:c, generatedAt} = $('Configure Feed Sources').first().json;
const positive = ['shortlistSize','maxShortlistPerTopic','freshHours','baselineHours','maxArticlesPerFeed','maxTopicsInReport','maxStoriesPerTopic','minBaselineStories','surgingMinStories','risingMinStories','minRisingPublishers'];
for (const k of positive) if (!Number.isFinite(c[k]) || c[k] <= 0) throw new Error('Invalid setting: ' + k);
for (const k of positive.filter(k => !['freshHours','baselineHours'].includes(k))) if (!Number.isInteger(c[k])) throw new Error(k + ' must be an integer');
if (c.maxArticlesPerFeed > 500) throw new Error('Keep maxArticlesPerFeed at 500 or less');
if (!Array.isArray(c.feeds) || c.feeds.length !== 4 || c.feeds.some(f => !f.name || !f.publisher || !/^https?:\/\/[^\s]+$/i.test(f.url))) throw new Error('Set four named public RSS/Atom feeds');
if (new Set(c.feeds.map(f => f.url)).size !== 4) throw new Error('Feed URLs must be different');
if (!Array.isArray(c.topics) || !c.topics.length || c.topics.length > 50 || c.topics.some(t => !t.name || !Array.isArray(t.keywords) || !t.keywords.length || t.keywords.some(k => typeof k !== 'string' || !k.trim()))) throw new Error('Set 1 to 50 named topics with keywords');
if (new Set(c.topics.map(t => t.name.toLowerCase().trim())).size !== c.topics.length) throw new Error('Topic names must be unique');
if (!Array.isArray(c.excludeKeywords) || c.excludeKeywords.some(k => typeof k !== 'string' || !k.trim())) throw new Error('Exclusions must be non-empty strings');
if (!(c.headlineSimilarity > 0 && c.headlineSimilarity <= 1 && c.surgingRatio > c.risingRatio && c.risingRatio > 1 && c.coolingRatio >= 0 && c.coolingRatio < 1)) throw new Error('Check similarity and momentum thresholds');
c.feeds = c.feeds.map(f => ({ ...f, publisher: f.publisher.trim().toLowerCase() }));

const now = Date.parse(generatedAt);
const horizon = (c.freshHours + c.baselineHours) * 3600000;
const norm = s => String(s || '').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const plain = s => String(s || '').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const contains = (text,term) => (' ' + text + ' ').includes(' ' + norm(term) + ' ');
const articles = [], feedHealth = [];
const rejected = {undated:0,old:0,future:0,excluded:0,invalid:0,duplicate:0,capped:0};
const seen = new Set();
for (let i = 0; i < 4; i++) {
  const rows = $('Fetch RSS Feed ' + (i + 1)).all().map(x => x.json);
  const f = c.feeds[i];
  const error = rows.some(r => r.error);
  const entries = rows.filter(r => r.title);
  let usable = [];
  for (const r of entries) {
    const title = plain(r.title);
    const link = String(r.link || '').trim();
    const published = Date.parse(r.isoDate || r.pubDate || r.published || r.date || '');
    if (!title || !/^https?:\/\/[^\s]+$/i.test(link)) { rejected.invalid++; continue; }
    if (!Number.isFinite(published)) { rejected.undated++; continue; }
    const age = now - published;
    if (age < 0) { rejected.future++; continue; }
    if (age > horizon) { rejected.old++; continue; }
    const summary = plain(r.contentSnippet || r.summary || r.content || '').slice(0,1600);
    if (c.excludeKeywords.some(k => contains(norm(title + ' ' + summary),k))) { rejected.excluded++; continue; }
    const noHash = link.split('#')[0];
    const parts = noHash.split('?');
    const query = (parts[1] || '').split('&').filter(q => q && !/^(utm_[^=]*|fbclid|gclid)=/i.test(q)).sort().join('&');
    const canonical = parts[0].replace(/\/$/,'') + (query ? '?' + query : '');
    usable.push({title,link,canonical,summary,published:new Date(published).toISOString(),ageHours:age/3600000,publisher:f.publisher,source:f.name});
  }
  usable.sort((a,b) => a.published.localeCompare(b.published));
  usable = usable.filter(a => {
    const key = a.publisher + '|' + a.canonical;
    if (seen.has(key)) { rejected.duplicate++; return false; }
    seen.add(key); return true;
  });
  const capped = usable.length > c.maxArticlesPerFeed;
  rejected.capped += Math.max(0,usable.length-c.maxArticlesPerFeed);
  usable = usable.slice(-c.maxArticlesPerFeed);
  feedHealth.push({name:f.name,state:error?'failed':entries.length?'ok':'empty',received:entries.length,retained:usable.length,capped});
  articles.push(...usable);
}
return [{json:{config:c,generatedAt,articles,feedHealth,rejected}}];

const d = $input.first().json;
const norm = s => String(s || '').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const has = (s,k) => (' ' + s + ' ').includes(' ' + norm(k) + ' ');
let unmatched = 0;
const articles = [];
for (const a of d.articles) {
  const title = norm(a.title), summary = norm(a.summary);
  const matches = d.config.topics.map((t,index) => ({name:t.name,index,score:t.keywords.reduce((n,k) => n + (has(title,k)?2:has(summary,k)?1:0),0)})).filter(t => t.score > 0).sort((a,b) => b.score-a.score || a.index-b.index);
  if (!matches.length) { unmatched++; continue; }
  const {summary:discard,...kept} = a;
  articles.push({...kept,topic:matches[0].name,titleKey:title,matchScore:matches[0].score});
}
return [{json:{...d,articles,unmatched}}];

const d = $input.first().json;
const stop = new Set('a an the and or of to in on for with from by at is are was were be as it its this that new says said'.split(' '));
const tokens = s => [...new Set(s.split(' ').filter(w => w.length > 1 && !stop.has(w)))];
const numbers = s => (s.match(/\b\d+\b/g) || []).sort().join('|');
const groups = [];
for (const a of [...d.articles].sort((a,b) => a.published.localeCompare(b.published) || a.title.localeCompare(b.title))) {
  const words = tokens(a.titleKey);
  let best = null, bestScore = 0;
  for (const g of groups) {
    if (g.topic !== a.topic) continue;
    const exact = g.canonical === a.canonical || g.titleKey === a.titleKey;
    if (!exact && (words.length < 4 || g.words.length < 4 || numbers(g.titleKey) !== numbers(a.titleKey))) continue;
    const common = words.filter(w => g.words.includes(w)).length;
    const similarity = exact ? 1 : common / (words.length + g.words.length - common);
    if (similarity >= d.config.headlineSimilarity && similarity > bestScore) { best = g; bestScore = similarity; }
  }
  if (!best) {
    best = {id:'story-' + (groups.length+1),topic:a.topic,title:a.title,titleKey:a.titleKey,canonical:a.canonical,words,articles:[]};
    groups.push(best);
  }
  best.articles.push(a);
}
return [{json:{...d,groups:groups.map(({words,titleKey,canonical,...g}) => g)}}];

const d = $input.first().json, c = d.config;
const fresh = g => g.articles.filter(a => a.ageHours < c.freshHours);
const base = g => g.articles.filter(a => a.ageHours >= c.freshHours);
const baselineTotal = d.groups.filter(g => base(g).length).length;
const warnings = ['Feed snapshot only: publishers may omit older entries. This is not a complete publishing history.'];
for (const f of d.feedHealth) {
  if (f.state !== 'ok') warnings.push(f.name + ': ' + f.state + '. Missing data may change the signal.');
  if (f.capped) warnings.push(f.name + ': article limit reached; older entries were dropped.');
}
if (baselineTotal < c.minBaselineStories) warnings.push('Limited baseline: only ' + baselineTotal + ' grouped stories in the earlier window.');
const quality = d.feedHealth.some(f => f.state !== 'ok' || f.capped) || baselineTotal < c.minBaselineStories ? 'Limited' : 'Snapshot';
const availablePublishers = new Set(c.feeds.map(f => f.publisher)).size;
const topics = c.topics.map(t => {
  const groups = d.groups.filter(g => g.topic === t.name);
  const recent = groups.filter(g => fresh(g).length), earlier = groups.filter(g => base(g).length);
  const rows = recent.flatMap(fresh);
  const publishers = [...new Set(rows.map(a => a.publisher))];
  const latest = rows.length ? Math.min(...rows.map(a => a.ageHours)) : null;
  const baselineEquivalent = earlier.length * c.freshHours / c.baselineHours;
  const ratio = (recent.length + 1) / (baselineEquivalent + 1);
  const freshness = latest === null ? 0 : Math.round(100 * Math.max(0,1-latest/c.freshHours));
  const diversity = Math.round(100 * publishers.length / availablePublishers);
  const growthScore = Math.max(0,Math.min(100,50 + 25 * Math.log2(ratio)));
  const activity = Math.min(1,recent.length/c.surgingMinStories);
  const momentum = recent.length ? Math.round(activity*(0.6*growthScore + 0.25*freshness + 0.15*diversity)) : 0;
  let status = 'Quiet';
  if (!recent.length && earlier.length) status = 'Cooling';
  else if (recent.length) {
    status = ratio < c.coolingRatio ? 'Cooling' : 'Active';
    if (ratio >= c.risingRatio && recent.length >= c.risingMinStories && publishers.length >= c.minRisingPublishers) status = 'Rising';
    if (ratio >= c.surgingRatio && recent.length >= c.surgingMinStories && publishers.length >= c.minRisingPublishers) status = 'Surging';
  }
  const signalQuality = quality === 'Limited' || earlier.length === 0 ? 'Limited' : quality;
  const examples = (recent.length ? recent : earlier).map(g => {
    const pool = recent.length ? fresh(g) : base(g);
    const representative = [...pool].sort((a,b) => b.published.localeCompare(a.published))[0];
    return {title:representative.title,link:representative.link,published:representative.published,sources:[...new Set(pool.map(a => a.source))]};
  }).sort((a,b) => b.published.localeCompare(a.published)).slice(0,c.maxStoriesPerTopic);
  return {topic:t.name,status,momentum,freshStories:recent.length,baselineStories:earlier.length,freshRatePerHour:Number((recent.length/c.freshHours).toFixed(3)),baselineRatePerHour:Number((earlier.length/c.baselineHours).toFixed(3)),ratio:Number(ratio.toFixed(2)),freshness,diversity,publisherCount:publishers.length,latestAgeHours:latest === null?null:Number(latest.toFixed(2)),quality:signalQuality,examples};
}).sort((a,b) => b.momentum-a.momentum || b.freshStories-a.freshStories || a.topic.localeCompare(b.topic));
return [{json:{...d,topics,warnings,quality,baselineTotal}}];

const d = $input.first().json, c = d.config;
const candidates = [];
for (const g of d.groups) {
  const recent = g.articles.filter(a => a.ageHours < c.freshHours);
  if (!recent.length) continue;
  const ordered = [...recent].sort((a,b) => b.published.localeCompare(a.published) || a.link.localeCompare(b.link));
  const sources = [...new Map(ordered.map(a => [a.publisher, {publisher:a.publisher, name:a.source, link:a.link}])).values()];
  const t = d.topics.find(t => t.topic === g.topic);
  const multiSource = sources.length >= 2;
  candidates.push({storyId:g.id, topic:g.topic, title:ordered[0].title, link:ordered[0].link,
    published:ordered[0].published, publisherCount:sources.length, sources,
    coverage:multiSource ? 'Multiple publishers' : 'Single publisher',
    momentum:t.momentum, quality:t.quality,
    reason:sources.length + ' publisher(s); topic ' + t.status.toLowerCase() + '; newest article ' + ordered[0].ageHours.toFixed(1) + 'h ago' + (t.quality === 'Limited' ? '; limited feed coverage' : '')});
}
candidates.sort((a,b) => Number(b.publisherCount >= 2)-Number(a.publisherCount >= 2) || b.momentum-a.momentum || b.publisherCount-a.publisherCount || b.published.localeCompare(a.published) || a.title.localeCompare(b.title));
const shortlist = [], counts = new Map();
for (const story of candidates) {
  if (shortlist.length >= c.shortlistSize) break;
  if ((counts.get(story.topic) || 0) >= c.maxShortlistPerTopic) continue;
  shortlist.push({...story, rank:shortlist.length+1});
  counts.set(story.topic, (counts.get(story.topic) || 0)+1);
}
const topics = d.topics.map(t => ({...t,shortlistedStories:counts.get(t.topic) || 0}));
return [{json:{...d,topics,shortlist}}];

const d = $input.first().json, c = d.config;
const esc = v => String(v ?? '').replace(/[&<>"']/g,ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const visible = d.topics.slice(0,c.maxTopicsInReport);
const colors = {Surging:'#b91c1c',Rising:'#047857',Active:'#1d4ed8',Cooling:'#92400e',Quiet:'#64748b'};
const summary = visible.map(t => '<tr><td>'+esc(t.topic)+'</td><td style="color:'+colors[t.status]+'">'+t.status+'</td><td>'+t.momentum+'</td><td>'+t.freshStories+'</td><td>'+t.baselineStories+'</td><td>'+t.ratio+'x</td><td>'+t.freshness+'</td><td>'+t.publisherCount+'</td><td>'+t.diversity+'</td><td>'+t.quality+'</td></tr>').join('');
const details = visible.map(t => '<section><h2>'+esc(t.topic)+' <small>'+t.status+'</small></h2>'+(t.examples.length?'<ul>'+t.examples.map(e => '<li><a href="'+esc(e.link)+'" rel="noreferrer noopener">'+esc(e.title)+'</a><br><small>'+esc(e.sources.join(' / '))+' · '+esc(e.published)+'</small></li>').join('')+'</ul>':'<p>No matching stories in either window.</p>')+'</section>').join('');
const health = d.feedHealth.map(f => '<tr><td>'+esc(f.name)+'</td><td>'+f.state+'</td><td>'+f.received+'</td><td>'+f.retained+'</td><td>'+(f.capped?'Yes':'No')+'</td></tr>').join('');
const shortlistHtml = '<section><h2>Stories to review first</h2><p>Up to '+c.shortlistSize+' stories, with no more than '+c.maxShortlistPerTopic+' per topic. Multiple-publisher groups come first. Coverage is not fact-checking: outlets may repeat the same source.</p>'+(d.shortlist.length?'<ol>'+d.shortlist.map(s => '<li><a href="'+esc(s.link)+'">'+esc(s.title)+'</a><br><small>'+esc(s.topic)+' · '+esc(s.coverage)+' · '+esc(s.reason)+'</small><br>'+s.sources.map(p => '<a href="'+esc(p.link)+'" rel="noreferrer noopener">'+esc(p.name)+'</a>').join(' / ')+'</li>').join('')+'</ol>':'<p>No fresh matching stories. Check the feeds and topic keywords.</p>')+'</section>';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RSS momentum brief</title><style>body{font:15px/1.6 system-ui,sans-serif;color:#172033;background:#f1f5f9;margin:0}main{max-width:1150px;margin:auto;padding:28px}section,.box{background:white;border:1px solid #dbe3ed;border-radius:10px;padding:20px;margin:20px 0}h1{margin-bottom:4px}h2{font-size:19px}small{color:#64748b}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}td,th{padding:10px;border-bottom:1px solid #e2e8f0}th{white-space:nowrap}a{color:#1d4ed8}li{margin:12px 0}.scroll{overflow:auto}.warn{border-left:4px solid #d97706}</style></head><body><main><h1>RSS momentum brief</h1><p>'+esc(d.generatedAt)+' · '+c.freshHours+'h fresh / preceding '+c.baselineHours+'h baseline</p><div class="box warn"><strong>Coverage: '+d.quality+'</strong><ul>'+d.warnings.map(w => '<li>'+esc(w)+'</li>').join('')+'</ul></div>'+(d.articles.length?'':'<div class="box"><strong>No matching articles survived the filters.</strong> Check feed health, dates, keywords and exclusions.</div>')+shortlistHtml+'<div class="box scroll"><p>Showing '+visible.length+' of '+d.topics.length+' topics. CSV includes every configured topic.</p><table><thead><tr><th>Topic</th><th>Status</th><th>Momentum /100</th><th>Fresh stories</th><th>Baseline stories</th><th>Ratio*</th><th>Freshness /100</th><th>Publishers</th><th>Diversity /100</th><th>Quality</th></tr></thead><tbody>'+summary+'</tbody></table></div>'+details+'<section class="scroll"><h2>Feed health</h2><table><tr><th>Feed</th><th>State</th><th>Received</th><th>Retained</th><th>Capped</th></tr>'+health+'</table><p>Rejected: '+esc(Object.entries(d.rejected).map(([k,v])=>k+': '+v).join(' · '))+'. Unmatched topics: '+d.unmatched+'.</p></section><section><h2>Reading this brief</h2><p>Counts are distinct headline groups in each window. A continuing story can appear once in both windows. Similarity grouping is approximate; each article belongs to its strongest matching topic.</p><p>*Ratio = (fresh stories + 1) / (baseline stories × fresh hours / baseline hours + 1). The added story smooths small samples. A zero baseline does not establish a new trend.</p><p>Freshness measures the age of the newest fresh article. Diversity is the share of configured publishers represented in fresh stories. Momentum combines growth (60%), freshness (25%) and diversity (15%), reduced for low story counts. It is an editorial sorting score, not a probability.</p><p>Surging and Rising need multiple stories and publishers. Active has fresh coverage without meeting growth thresholds; Cooling has declining coverage; Quiet has no matched stories. Limited quality calls for manual review. These are signals from the returned feed snapshot.</p></section></main></body></html>';
const headers = ['generated_at','topic','shortlisted_stories','status','momentum','fresh_stories','baseline_stories','fresh_rate_per_hour','baseline_rate_per_hour','smoothed_ratio','freshness','publisher_count','diversity','latest_age_hours','quality','fresh_hours','baseline_hours','feed_health','warnings'];
const cell = v => {
  let s = String(v ?? '');
  if (typeof v === 'string' && /^[\s]*[=+\-@]/.test(s)) s = "'" + s;
  return '"' + s.replace(/"/g,'""') + '"';
};
const rows = d.topics.map(t => [d.generatedAt,t.topic,t.shortlistedStories,t.status,t.momentum,t.freshStories,t.baselineStories,t.freshRatePerHour,t.baselineRatePerHour,t.ratio,t.freshness,t.publisherCount,t.diversity,t.latestAgeHours,t.quality,c.freshHours,c.baselineHours,d.feedHealth.map(f=>f.name+': '+f.state+(f.capped?' (capped)':'')).join(' | '),d.warnings.join(' | ')]);
const csv = '\uFEFF' + [headers,...rows].map(r => r.map(cell).join(',')).join('\r\n') + '\r\n';
return [{json:{generatedAt:d.generatedAt,topicCount:d.topics.length,quality:d.quality,html,csv}}];
